fn normalize_path_arg(value: &str) -> std::io::Result {
 let path = crate::worktree::expand_tilde_path(value);
 let absolute = if path.is_absolute() {
 path
 } else {
 std::env::current_dir()?.join(path)
 };
 Ok(absolute.display().to_string())
}

